function createEnv(sdk) {
  var STEPS = 500;
  var SLOT_COUNT = 4;
  var rng, basketX, apples, tick, done;
  var terms = [0, 0, 0, 0];
  var obs = new Array(13);

  function spawnApple() {
    var i;
    for (i = 0; i < SLOT_COUNT; i += 1) {
      if (!apples[i].active) {
        apples[i].active = true;
        apples[i].x = rng.range(65, 735);
        apples[i].y = 24;
        apples[i].speed = rng.range(3.0, 3.8);
        return;
      }
    }
  }

  function basketLeft() {
    return basketX - 48;
  }

  return {
    reset: function (seed) {
      rng = sdk.rng(seed);
      basketX = 400;
      tick = 0;
      done = false;
      terms[0] = 0;
      terms[1] = 0;
      terms[2] = 0;
      terms[3] = 0;
      apples = [];
      var i;
      for (i = 0; i < SLOT_COUNT; i += 1) {
        apples.push({ active: false, x: 0, y: 0, speed: 0 });
      }
      spawnApple();
    },

    step: function (action) {
      if (done) return;

      var move = 0;
      if (action === 0) move = -1;
      else if (action === 2) move = 1;

      if (move !== 0) {
        basketX = sdk.clamp(basketX + move * 7, 52, 748);
        terms[3] += 1 / STEPS;
      }

      var i;
      for (i = 0; i < SLOT_COUNT; i += 1) {
        var apple = apples[i];
        if (!apple.active) continue;

        var dx = Math.abs(apple.x - basketX);
        var horizontalCloseness = Math.max(0, 1 - dx / 360);
        var heightWeight = 0.25 + 0.75 * Math.min(1, apple.y / 465);
        terms[0] += horizontalCloseness * heightWeight / (STEPS * SLOT_COUNT);

        apple.y += apple.speed;

        if (apple.y >= 420 && Math.abs(apple.x - basketX) <= 49) {
          apple.active = false;
          terms[1] += 1;
        } else if (apple.y > 465) {
          apple.active = false;
          terms[2] += 1;
        }
      }

      tick += 1;
      if (tick % 42 === 0) spawnApple();
      if (tick >= STEPS) done = true;
    },

    observe: function () {
      obs[0] = (basketX - 400) / 400;
      var i;
      for (i = 0; i < SLOT_COUNT; i += 1) {
        var base = 1 + i * 3;
        if (apples[i].active) {
          obs[base] = (apples[i].x - 400) / 400;
          obs[base + 1] = apples[i].y / 250 - 1;
          obs[base + 2] = 1;
        } else {
          obs[base] = 0;
          obs[base + 1] = 0;
          obs[base + 2] = 0;
        }
      }
      return obs;
    },

    get done() {
      return done;
    },

    terms: terms,

    render: function (draw, ghost) {
      if (!ghost) {
        draw.clear(sdk.colors.bg);
        draw.line(25, 472, 775, 472, sdk.colors.dim, 2);
        var i;
        for (i = 0; i < SLOT_COUNT; i += 1) {
          if (apples[i].active) {
            draw.circle(apples[i].x, apples[i].y, 10, sdk.colors.bad);
            draw.line(apples[i].x, apples[i].y - 8, apples[i].x + 5, apples[i].y - 13, sdk.colors.good, 3);
          }
        }
        draw.text("Catches: " + terms[1], 24, 32, sdk.colors.fg, 18);
      }

      draw.poly([
        basketLeft(), 426,
        basketX + 48, 426,
        basketX + 38, 460,
        basketX - 38, 460
      ], sdk.colors.accent, true);
      draw.line(basketX - 48, 426, basketX + 48, 426, sdk.colors.good, 4);
    },

    humanAct: function (input) {
      if (input.held.has("ArrowLeft")) return 0;
      if (input.held.has("ArrowRight")) return 2;
      return 1;
    }
  };
}
